    <script>
        document.addEventListener("DOMContentLoaded", function() {
            const mobileMenuToggle = document.querySelector('[data-collapse-toggle="mobile-menu-2"]');
            const mobileMenu = document.getElementById('mobile-menu-2');

            mobileMenuToggle.addEventListener('click', function() {
                const expanded = mobileMenuToggle.getAttribute('aria-expanded') === 'true' || false;
                mobileMenuToggle.setAttribute('aria-expanded', !expanded);
                mobileMenu.classList.toggle('hidden');
            });

            // Menutup menu dropdown jika pengguna mengklik di luar area menu
            document.addEventListener('click', function(event) {
                const isClickInsideMenu = mobileMenu.contains(event.target);
                const isClickOnToggle = mobileMenuToggle.contains(event.target);
                if (!isClickInsideMenu && !isClickOnToggle) {
                    mobileMenuToggle.setAttribute('aria-expanded', 'false');
                    mobileMenu.classList.add('hidden');
                }
            });
        });
    </script>

